# Run from repository root. All exported figures are ggplot2 objects.
# Batch 01/02: simulated examples. Reference 12: built-in observational data.
library(ggplot2)
set.seed(42)
pal<-c('#374E55','#DF8F44','#79AF97','#6A6599','#00A1D5')
theme_set(theme_classic(base_size=11)+theme(legend.position='top',legend.title=element_blank(),legend.key.height=unit(3,'mm'),legend.key.width=unit(5,'mm'),axis.line=element_line(linewidth=.35),axis.ticks=element_line(linewidth=.3),plot.margin=margin(10,14,10,10),strip.background=element_rect(fill='#F1F3F4',colour=NA)))
saveplot<-function(p,dir,name,w=7,h=5.5){stopifnot(inherits(p,'ggplot'));dir.create(dir,recursive=TRUE,showWarnings=FALSE);p<-p+labs(title=NULL,subtitle=NULL,caption=NULL);ggsave(file.path(dir,paste0(name,'.png')),p,width=w,height=h,dpi=300,bg='white')}
colors<-function(p)p+scale_colour_manual(values=pal)+scale_fill_manual(values=pal)
read<-function(dir,n)read.csv(file.path(dir,paste0(n,'-data.csv')),check.names=FALSE)
batch1<-function(dir){
 d<-read(dir,'01-distribution');p<-ggplot(d,aes(group,value,fill=group,colour=group))+geom_violin(alpha=.18,linewidth=.4,trim=TRUE)+geom_point(position=position_jitter(width=.1,seed=42),size=1.2,alpha=.55)+geom_boxplot(width=.12,outlier.shape=NA,fill='white',linewidth=.4)+labs(x=NULL,y='Response (a.u.)')+theme(legend.position='none');saveplot(colors(p),dir,'01-distribution')
 d<-read(dir,'02-volcano');d$status<-ifelse(d$FDR<.05 & abs(d$log2FC)>1,ifelse(d$log2FC>0,'Upregulated','Downregulated'),'Not significant');p<-ggplot(d,aes(log2FC,-log10(pmax(FDR,1e-15)),colour=status))+geom_point(size=1,alpha=.7)+geom_vline(xintercept=c(-1,1),linetype=2,colour='grey65')+geom_hline(yintercept=-log10(.05),linetype=2,colour='grey65')+scale_colour_manual(values=c('Downregulated'=pal[1],'Upregulated'=pal[2],'Not significant'='#CAD2D8'))+labs(x=expression(log[2]~'fold change'),y=expression(-log[10]~'adjusted P'));saveplot(p,dir,'02-volcano')
 d<-read(dir,'03-forest');d$subgroup<-factor(d$subgroup,levels=rev(d$subgroup));p<-ggplot(d,aes(HR,subgroup))+geom_vline(xintercept=1,linetype=2,colour='grey60')+geom_segment(aes(x=lower,xend=upper,yend=subgroup),colour=pal[1],linewidth=.7)+geom_point(shape=15,size=3,colour=pal[1])+scale_x_log10()+labs(x='Hazard ratio (95% CI)',y=NULL);saveplot(p,dir,'03-forest')
 d<-read(dir,'04-heatmap');m<-as.matrix(d[,-1]);z<-expand.grid(gene=seq_len(nrow(m)),sample=seq_len(ncol(m)));z$value<-as.vector(m);p<-ggplot(z,aes(factor(sample),factor(gene,levels=rev(1:nrow(m))),fill=value))+geom_tile()+scale_fill_gradient2(low='#355C7D',mid='#F7F5F0',high='#B65C50',limits=c(-3,3),name='Z')+labs(x='Sample',y='Gene')+theme(axis.line=element_blank(),axis.ticks=element_blank(),legend.position='right');saveplot(p,dir,'04-heatmap')
 d<-read(dir,'05-trend');z<-rbind(data.frame(week=d$week,mean=d$control,ci=d$CI_half_width,group='Control'),data.frame(week=d$week,mean=d$treatment,ci=d$CI_half_width,group='Treatment'));p<-ggplot(z,aes(week,mean,colour=group,fill=group))+geom_ribbon(aes(ymin=mean-ci,ymax=mean+ci),alpha=.15,colour=NA)+geom_line(linewidth=.7)+geom_point(shape=21,fill='white',size=2)+labs(x='Time (weeks)',y='Response (a.u.)');saveplot(colors(p),dir,'05-trend')
}
batch2<-function(dir){
 d<-read(dir,'06-pca');pc<-prcomp(d[,-1],scale.=TRUE);v<-100*pc$sdev^2/sum(pc$sdev^2);z<-data.frame(pc$x[,1:2],group=d$group);p<-ggplot(z,aes(PC1,PC2,colour=group,fill=group))+stat_ellipse(geom='polygon',alpha=.08,linewidth=.4)+geom_point(aes(shape=group),size=2.1,alpha=.8)+labs(x=sprintf('PC1 (%.1f%%)',v[1]),y=sprintf('PC2 (%.1f%%)',v[2]));saveplot(colors(p),dir,'06-pca')
 d<-read(dir,'07-roc');z<-do.call(rbind,lapply(c('scoreA','scoreB'),function(k){s<-d[[k]];th<-c(Inf,sort(unique(s),decreasing=TRUE),-Inf);data.frame(FPR=sapply(th,function(t)mean(s[d$outcome==0]>=t)),TPR=sapply(th,function(t)mean(s[d$outcome==1]>=t)),model=k)}));p<-ggplot(z,aes(FPR,TPR,colour=model))+geom_abline(linetype=2,colour='grey70')+geom_step(linewidth=.8)+coord_equal()+theme(panel.grid.major=element_line(colour='#E8ECEE',linewidth=.2))+labs(x='1 - Specificity',y='Sensitivity');saveplot(colors(p),dir,'07-roc')
 d<-read(dir,'08-paired');z<-rbind(data.frame(subject=d$subject,time='Baseline',value=d$before),data.frame(subject=d$subject,time='Follow-up',value=d$after));p<-ggplot(z,aes(time,value))+geom_line(aes(group=subject),colour='grey75',alpha=.6,linewidth=.35)+geom_point(aes(colour=time),size=2.2,shape=21,fill='white',stroke=.7)+labs(x=NULL,y='Biomarker concentration (a.u.)');saveplot(colors(p)+theme(legend.position='none'),dir,'08-paired')
 d<-read(dir,'09-agreement');z<-data.frame(mean=(d$methodA+d$methodB)/2,diff=d$methodB-d$methodA);mu<-mean(z$diff);li<-mu+c(-1,1)*1.96*sd(z$diff);p<-ggplot(z,aes(mean,diff))+geom_point(colour=pal[1],alpha=.65,size=2)+geom_hline(yintercept=mu,colour=pal[2])+geom_hline(yintercept=li,linetype=2,colour=pal[1])+labs(x='Mean of methods A and B',y='Difference (B - A)');saveplot(p,dir,'09-agreement')
 d<-read(dir,'10-correlation');m<-as.matrix(d[,-1]);z<-expand.grid(x=1:nrow(m),y=1:ncol(m));z$r<-as.vector(m);z<-z[z$x<=z$y,];p<-ggplot(z,aes(factor(x),factor(y,levels=8:1)))+geom_point(aes(size=abs(r),fill=r),shape=21,colour='white',stroke=.25)+scale_size_area(max_size=12,limits=c(0,1))+scale_fill_gradient2(low='#355C7D',mid='#F7F5F0',high='#B65C50',limits=c(-1,1))+coord_equal()+labs(x='Marker',y='Marker',fill='Pearson r',size='|r|')+theme(axis.line=element_blank(),axis.ticks=element_blank());saveplot(p+guides(size='none')+theme(legend.position='right',legend.title=element_text()),dir,'10-correlation')
}
reference<-function(dir){
 b<-ggplot(iris,aes(Sepal.Length,fill=Species,colour=Species))
 saveplot(colors(ggplot(mtcars,aes(factor(cyl),fill=factor(gear)))+geom_bar(position='fill',colour='white',linewidth=.3)+labs(x='Cylinders',y='Proportion')),dir,'01-stacked-proportions')
 # Half-density polygons, boxplots and individual observations, all ggplot layers.
 ds<-do.call(rbind,lapply(1:3,function(i){v<-iris$Sepal.Length[iris$Species==levels(iris$Species)[i]];d<-density(v);data.frame(x=c(d$x,rev(d$x)),y=c(i+d$y/max(d$y)*.4,rep(i,length(d$x))),Species=levels(iris$Species)[i])}));z<-iris;z$y<-as.numeric(z$Species)
 p<-ggplot()+geom_polygon(data=ds,aes(x,y,fill=Species,colour=Species),alpha=.35,linewidth=.4)+geom_point(data=z,aes(Sepal.Length,y-.18,colour=Species),position=position_jitter(height=.06,width=0,seed=42),size=1.1,alpha=.6)+geom_boxplot(data=z,aes(Sepal.Length,y-.07,group=Species,colour=Species),orientation='y',width=.08,outlier.shape=NA,fill='white')+scale_y_continuous(breaks=1:3,labels=levels(z$Species))+labs(x='Sepal length (cm)',y=NULL)+theme(legend.position='none');saveplot(colors(p),dir,'02-raincloud')
 saveplot(colors(b+geom_histogram(binwidth=.25,boundary=4,colour='white')+facet_wrap(~Species,nrow=1)+labs(x='Sepal length (cm)',y='Count')+theme(legend.position='none')),dir,'03-faceted-histogram')
 saveplot(colors(b+geom_density(alpha=.22,linewidth=.6)+labs(x='Sepal length (cm)',y='Density')),dir,'04-density-overlay')
 saveplot(colors(ggplot(iris,aes(Species,Sepal.Length,fill=Species,colour=Species))+geom_violin(alpha=.2,trim=TRUE)+geom_boxplot(width=.12,fill='white',outlier.shape=NA)+geom_jitter(width=.08,size=1,alpha=.55)+labs(x=NULL,y='Sepal length (cm)')+theme(legend.position='none')),dir,'05-violin-observations')
 saveplot(colors(b+geom_histogram(position='identity',binwidth=.25,alpha=.35,linewidth=.3)+labs(x='Sepal length (cm)',y='Count')),dir,'06-overlaid-histograms')
 saveplot(ggplot(na.omit(airquality),aes(Temp,Ozone))+geom_bin_2d(binwidth=c(5,15))+scale_fill_gradient(low='#F7F5F0',high='#374E55')+labs(x='Temperature (F)',y='Ozone (ppb)',fill='Count'),dir,'07-binned-density')
 saveplot(colors(ggplot(mtcars,aes(factor(cyl),mpg,fill=factor(am,labels=c('Automatic','Manual'))))+geom_boxplot(width=.65,linewidth=.4)+labs(x='Cylinders',y='Fuel economy (mpg)')),dir,'08-grouped-boxplots')
 means<-aggregate(weight~group,PlantGrowth,mean);saveplot(colors(ggplot(PlantGrowth,aes(weight,fill=group,colour=group))+geom_density(alpha=.25)+geom_vline(data=means,aes(xintercept=weight,colour=group),linetype=2)+labs(x='Dried plant weight',y='Density')),dir,'09-density-means')
 d<-mtcars;d$label<-rownames(d);ix<-c(3,7,9,16,20,28);saveplot(ggplot(d,aes(wt,mpg))+geom_point(colour=pal[1],size=2)+geom_text(data=d[ix,],aes(label=label),vjust=-.8,size=3,check_overlap=TRUE)+scale_y_continuous(expand=expansion(mult=c(.05,.15)))+labs(x='Weight (1000 lb)',y='Fuel economy (mpg)'),dir,'10-labeled-scatter')
 saveplot(colors(ggplot(PlantGrowth,aes(group,weight,fill=group,colour=group))+geom_boxplot(width=.35,alpha=.15,outlier.shape=NA)+geom_jitter(width=.09,size=2)+stat_summary(fun=mean,geom='point',shape=23,fill='white',size=3)+labs(x=NULL,y='Dried plant weight')+theme(legend.position='none')),dir,'11-box-jitter')
 d<-as.data.frame(table(mtcars$cyl));saveplot(colors(ggplot(d,aes(x=2,y=Freq,fill=Var1))+geom_col(colour='white',linewidth=.5)+geom_text(aes(label=Freq),position=position_stack(vjust=.5),size=4)+coord_polar(theta='y')+xlim(.5,2.5)+theme_void()+theme(legend.position='bottom')),dir,'12-donut')
}



